"""Self-contained private human review form; no network or automatic submission."""
import json


def write_ui(path,packets,template):
    payload=json.dumps({"packets":packets,"form":template},ensure_ascii=False).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026")
    page='''<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Day 2 匿名人工判断</title><style>
body{max-width:1100px;margin:25px auto;padding:0 18px;font:15px/1.6 system-ui,"Microsoft YaHei",sans-serif;color:#233247;background:#f5f7fa}header,.card,.evidence{background:white;border:1px solid #dce2ec;border-radius:8px;padding:18px;margin:12px 0}h1{font-size:25px}h2{font-size:18px}input,select,textarea,button{font:inherit;padding:8px;border:1px solid #bdc8d8;border-radius:5px}textarea{width:97%;min-height:65px}button{cursor:pointer;background:#e8effc}pre{white-space:pre-wrap;word-break:break-word}.warn{background:#fff2d4;padding:12px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{border-bottom:1px solid #e4e9ef;padding:6px;text-align:left;word-break:break-all}summary{cursor:pointer}label{display:block;margin:5px 0}.bar{position:sticky;top:0;background:#f5f7fa;padding:12px 0;z-index:1}.small{font-size:12px;color:#647189}.original{white-space:pre-wrap}#packet{max-width:100%}</style>
<h1>Day 2 匿名人工判断</h1><div class="warn">仅供独立人类评审。请勿查看 Silver 标签、另一评审者结果或诊断排序。这里没有预填人工判断。未填写和“无法判断”是不同状态；请导出文件保存进度，关闭页面不会自动保存。</div>
<header><label>真实评审者 ID <input id="reviewer" autocomplete="off"></label><label><input id="human" type="checkbox"> 我确认这些判断由我本人作为人类评审完成。</label><label><input id="blind" type="checkbox"> 我未查看 Silver、另一评审者结果或诊断排序。</label><button id="save">导出当前判断 JSON</button> <label>导入自己的进度文件 <input type="file" id="load" accept="application/json,.json"></label><p id="progress" class="small"></p></header>
<div class="bar"><select id="packet"></select></div><div id="content"></div>
<script id="payload" type="application/json">__PAYLOAD__</script><script>
'use strict';const root=JSON.parse(document.getElementById('payload').textContent);let form=root.form;const packets=root.packets;
function el(t,x){const n=document.createElement(t);if(x!==undefined)n.textContent=x;return n;}function detail(title,node){const d=el('details');d.append(el('summary',title),node);return d;}
const select=document.getElementById('packet');for(let i=0;i<packets.length;i++){const o=el('option',(i+1)+' / '+packets.length+' · '+packets[i].packet_id);o.value=i;select.append(o);}
function row(p,c){return form.judgments.find(j=>j.packet_id===p.packet_id&&j.candidate_id===c.candidate_id);}
function progress(){document.getElementById('progress').textContent='已填写 '+form.judgments.filter(j=>j.annotation_status!=='UNFILLED').length+' / '+form.judgments.length+' 项；请定期导出。';}
function render(){const p=packets[Number(select.value)||0],out=document.getElementById('content');out.replaceChildren();const q=el('section');q.className='card';q.append(el('h2',p.query.topic),el('p','查询类型：'+p.query.query_basis),el('p',p.query.goal||'仅 Topic；未给出个人 Goal。'));q.append(detail('相关性 rubric（0–3、并列、无法判断）',el('pre',JSON.stringify(p.rubric,null,2))));out.append(q);
const evid=el('section');evid.className='evidence';evid.append(el('h2','本包可用聚合证据 · '+p.evidence.length+' 项'));const filter=el('input');filter.placeholder='按 metric、operation 或状态筛选';evid.append(filter);const table=el('table');evid.append(table);function draw(){table.replaceChildren();const head=el('tr');for(const s of ['Evidence ID','指标 / 操作 / 窗口','状态','值 / 单位'])head.append(el('th',s));table.append(head);const term=filter.value.toLowerCase();for(const e of p.evidence.filter(e=>JSON.stringify(e).toLowerCase().includes(term))){const tr=el('tr');tr.append(el('td',e.evidence_id),el('td',e.metric+' / '+e.operation+' / '+e.window_days+'d'),el('td',e.status),el('td',JSON.stringify(e.value)+' '+e.unit));table.append(tr);}}filter.addEventListener('input',draw);draw();out.append(evid);
for(const c of p.candidates){const j=row(p,c),card=el('section');card.className='card';card.append(el('div',c.candidate_id),el('h2',c.title));const text=el('p',c.text);text.className='original';card.append(detail('完整来源正文',text));const grade=el('select');for(const [v,t] of [['UNFILLED','尚未填写'],['null','无法判断（null）'],['0','0 · 不相关'],['1','1 · 相关背景'],['2','2 · 直接相关'],['3','3 · 尤其具体相关']]){const o=el('option',t);o.value=v;grade.append(o);}grade.value=j.annotation_status==='UNFILLED'?'UNFILLED':j.grade===null?'null':String(j.grade);grade.addEventListener('change',()=>{j.grade=grade.value==='null'||grade.value==='UNFILLED'?null:Number(grade.value);j.annotation_status=grade.value==='UNFILLED'?'UNFILLED':'ACCEPTED';progress();});card.append(el('label','相关性等级'),grade);const reason=el('textarea');reason.placeholder='判断依据、缺失上下文、并列或无法判断的原因';reason.value=j.reason_code;reason.addEventListener('input',()=>j.reason_code=reason.value);card.append(reason);
const sources=el('div');for(const s of c.source_spans){const label=el('label'),cb=el('input');cb.type='checkbox';cb.checked=j.source_span_ids.includes(s.span_id);cb.addEventListener('change',()=>{j.source_span_ids=cb.checked?[...new Set([...j.source_span_ids,s.span_id])]:j.source_span_ids.filter(x=>x!==s.span_id);});label.append(cb,document.createTextNode(s.span_id+' · '+(s.heading?s.heading+' / ':'')+s.text));sources.append(label);}card.append(detail('选择依据的来源块（接受判断至少选一项）',sources));
const refs=el('select');refs.multiple=true;refs.size=Math.min(6,Math.max(2,p.evidence.length));for(const e of p.evidence){const o=el('option',e.metric+' / '+e.operation+' / '+e.window_days+'d · '+e.evidence_id);o.value=e.evidence_id;o.selected=j.evidence_ids.includes(e.evidence_id);refs.append(o);}refs.addEventListener('change',()=>j.evidence_ids=[...refs.selectedOptions].map(o=>o.value));card.append(detail('选择个人证据引用（可不选；不得推断未观测状态）',refs));out.append(card);}progress();}
select.addEventListener('change',render);document.getElementById('save').addEventListener('click',()=>{form.reviewer_id=document.getElementById('reviewer').value.trim()||null;form.human_attestation=document.getElementById('human').checked;form.annotator_type=form.human_attestation?'HUMAN':null;form.saw_silver_or_ranker_outputs=document.getElementById('blind').checked?false:null;const a=el('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(form,null,2)],{type:'application/json'}));a.download='day2-human-'+form.slot+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});document.getElementById('load').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{const saved=JSON.parse(await file.text());const ids=x=>JSON.stringify(x.judgments.map(j=>j.packet_id+'|'+j.candidate_id).sort());if(saved.slot!==form.slot||ids(saved)!==ids(form))throw Error('文件不属于本评审包');form=saved;document.getElementById('reviewer').value=form.reviewer_id||'';document.getElementById('human').checked=form.human_attestation===true;document.getElementById('blind').checked=form.saw_silver_or_ranker_outputs===false;render();}catch(e){alert('导入失败：'+e.message);}});render();
</script></html>'''.replace('__PAYLOAD__',payload)
    with path.open('x',encoding='utf-8') as stream:stream.write(page)
